<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {CompanyClient} from '$lib/utils/company-workspace';
 export let companyId:string;
 export let actorId:string;
 export let accessSignal:AbortSignal;
 export let bots:{id:string;name:string}[]=[];
 let client:CompanyClient,loading=true,busy=false,error='',notice='',key='',canManage=false;
 let connections:any[]=[],botId='',selection:any=null,options:any[]=[],choice='';
 const value=(connection:string|null,model:string)=>JSON.stringify([connection,model]);
 function revoked(){key='';selection=null;connections=[];options=[];client?.close();}
 async function load(){loading=true;error='';try{const data=await client.request('/provider-connections');if(accessSignal.aborted)return;if(!Array.isArray(data.connections)||typeof data.canManage!=='boolean')throw Error('Provider status could not be verified.');connections=data.connections.filter((c:any)=>c.status==='active'&&c.provider==='openrouter');canManage=data.canManage;}catch(cause){if(!accessSignal.aborted)error=(cause as Error).message;}finally{loading=false;}}
 async function selectBot(){selection=null;options=[];choice='';if(!botId)return;const id=botId;try{const [catalog,current]=await Promise.all([client.request('/bots/'+encodeURIComponent(id)+'/provider-options','GET',undefined,undefined,true),client.request('/bots/'+encodeURIComponent(id)+'/provider-selection')]);if(accessSignal.aborted||id!==botId)return;if(current.botId!==id||!Number.isSafeInteger(current.configurationRevision)||!Array.isArray(catalog.options))throw Error('Bot provider selection could not be verified.');selection=current;options=catalog.options.filter((o:any)=>o.provider==='openrouter'&&Array.isArray(o.models)&&typeof o.connectionId==='string');choice=current.connectionId&&current.model?value(current.connectionId,current.model):'';}catch(cause){if(!accessSignal.aborted)error=(cause as Error).message;}}
 async function connect(){if(busy||!key.trim()||!canManage)return;const secret=key.trim();key='';busy=true;error='';notice='';try{const result=await client.request('/provider-connections','POST',{provider:'openrouter',credential:{apiKey:secret}},undefined,true);if(typeof result.connectionId!=='string')throw Error('The connection receipt could not be verified.');notice='Company key saved. Choose a bot and its model below.';await load();await selectBot();}catch(cause){if(!accessSignal.aborted)error=(cause as Error).message;}finally{busy=false;}}
 async function save(){if(busy||!selection||!choice)return;const found=options.flatMap(o=>o.models.map((model:string)=>({connectionId:o.connectionId,model}))).find(o=>value(o.connectionId,o.model)===choice);if(!found)return;busy=true;error='';notice='';try{await client.request('/bots/'+encodeURIComponent(botId)+'/provider-selection','PUT',{...found,expectedRevision:selection.configurationRevision},undefined,true);await selectBot();notice='Bot model choice saved. A response is verified only after a successful chat run.';}catch(cause){if(!accessSignal.aborted)error=(cause as Error).message;}finally{busy=false;}}
 onMount(()=>{if(!actorId||accessSignal.aborted){loading=false;return;}client=new CompanyClient(companyId,()=>localStorage.token||'');accessSignal.addEventListener('abort',revoked,{once:true});void load();});
 onDestroy(()=>{accessSignal.removeEventListener('abort',revoked);revoked();});
</script>

<section class="provider" aria-label="Local company model connection">
 <header><div><h3>Model connection</h3><p>Use your company’s OpenRouter key and select a model for each participating bot.</p></div><button type="button" disabled={busy||loading} on:click={load}>Refresh</button></header>
 {#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if loading}<p>Checking saved company connections…</p>{:else}
  <p>{connections.length ? connections.length+' saved OpenRouter connection(s).' : 'No active OpenRouter company connection is saved.'}</p>
  {#if canManage}<form on:submit|preventDefault={connect}><label>OpenRouter API key<input type="password" bind:value={key} autocomplete="off" spellcheck="false" placeholder="sk-or-v1-…" disabled={busy}/></label><button class="primary" disabled={busy||!key.trim()}>Save company key</button></form><p class="hint">The key is sent to this installation’s provider vault. It is never saved in browser storage. Saving does not send a model request.</p>{:else}<p class="hint">A company owner or administrator manages credentials.</p>{/if}
  <label>Bot<select bind:value={botId} on:change={selectBot} disabled={busy}><option value="">Choose a bot</option>{#each bots as bot}<option value={bot.id}>{bot.name}</option>{/each}</select></label>
  {#if selection}<p class="hint">Saved selection: {selection.status}{selection.model?' · '+selection.model:''}</p><label>Available model<select bind:value={choice} disabled={busy}><option value="">Choose a saved connection and model</option>{#each options as option}{#each option.models as model}<option value={value(option.connectionId,model)}>{option.provider} · {model}</option>{/each}{/each}</select></label><button class="primary" type="button" disabled={busy||!choice} on:click={save}>Use model for this bot</button>{#if !options.length}<p class="hint">No selectable model is available. Save a connection first, then refresh.</p>{/if}{/if}
 {/if}
</section>
<style>.provider{padding:20px;color:#17243f;font-size:13px}header{display:flex;justify-content:space-between;gap:16px}h3{font-size:16px;margin:0}p{line-height:1.6}header p,.hint{color:#71809a;font-size:12px}.hint{margin:10px 0}label{display:grid;gap:7px;margin:16px 0;font-size:12px;font-weight:600}input,select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #dfe6f2;border-radius:8px;background:#fafdff;color:#17243f;font:inherit}button{cursor:pointer;border:1px solid #dfe6f2;background:#fff;border-radius:8px;padding:9px 12px;color:#475569;font:inherit;align-self:flex-start}button.primary{background:#2563eb;color:white;border-color:#2563eb}button:disabled{opacity:.45;cursor:default}.error{color:#be123c;background:#fff0f2;padding:10px;border-radius:8px}.notice{color:#166534;background:#f0fdf4;padding:10px;border-radius:8px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #9cb7ff;outline-offset:2px}</style>
